import os
roots=['/inputs','/work','/home','/opt','/etc']
needle='SHOPIFY_API_SECRET'
found=[]
for root in roots:
    for dirpath, dirnames, filenames in os.walk(root):
        # prune very large/irrelevant dirs in /etc
        if dirpath.startswith('/etc/ssl') or dirpath.startswith('/etc/alternatives'):
            continue
        for fn in filenames:
            p=os.path.join(dirpath,fn)
            try:
                with open(p,'rb') as f:
                    data=f.read()
                if needle.encode() in data:
                    found.append(p)
            except Exception:
                pass
print('found',found)
